using System.ComponentModel.DataAnnotations;

namespace foodiya.app.Identity.Contracts.Authentication;

/// <summary>A Google ID token and device metadata required to start an authenticated session.</summary>
public sealed record GoogleSignInRequest
{
    /// <summary>Google-issued OpenID Connect ID token obtained by the client.</summary>
    [Required]
    public required string IdToken { get; init; }

    /// <summary>Stable identifier generated by this application installation.</summary>
    [Required, StringLength(200, MinimumLength = 8)]
    public required string DeviceInstallationId { get; init; }

    /// <summary>Client platform, such as ios, android, web, or windows.</summary>
    [StringLength(30)]
    public string? Platform { get; init; }

    /// <summary>User-friendly device name.</summary>
    [StringLength(150)]
    public string? DeviceName { get; init; }

    /// <summary>Operating-system version reported by the client.</summary>
    [StringLength(50)]
    public string? OsVersion { get; init; }

    /// <summary>Client application version.</summary>
    [StringLength(50)]
    public string? AppVersion { get; init; }
}
